MOTIF_NAME = "fortified layered influence polarity"
MOTIF_DESCRIPTION = "The evaluated side has favorable layered influence after accounting for komi, weak groups, isolated stones, contact pressure, and well-libertied groups."


def motif(board_rows: list[str], color: str) -> bool:
    if color not in ("B", "W") or not board_rows:
        return False

    height = len(board_rows)
    width = len(board_rows[0])
    if width == 0 or any(len(row) != width for row in board_rows):
        return False
    if any(point not in ".BW" for row in board_rows for point in row):
        return False

    opponent = "W" if color == "B" else "B"
    counts = {"B": 0, "W": 0}
    weak_burden = {"B": 0, "W": 0}
    detached = {"B": 0, "W": 0}
    pressured = {"B": 0, "W": 0}
    fortified = {"B": 0, "W": 0}
    seen: set[tuple[int, int]] = set()

    prefix = [[0] * (width + 1) for _ in range(height + 1)]

    for row_index, row in enumerate(board_rows):
        running = 0
        for column_index, stone in enumerate(row):
            running += int(stone == color) - int(stone == opponent)
            prefix[row_index + 1][column_index + 1] = (
                prefix[row_index][column_index + 1] + running
            )

            if stone not in ("B", "W"):
                continue

            counts[stone] += 1
            nearby_friend = False
            orthogonal_enemies = 0

            for row_delta in (-1, 0, 1):
                for column_delta in (-1, 0, 1):
                    if row_delta == 0 and column_delta == 0:
                        continue
                    neighbor_row = row_index + row_delta
                    neighbor_column = column_index + column_delta
                    if not (
                        0 <= neighbor_row < height
                        and 0 <= neighbor_column < width
                    ):
                        continue

                    neighbor = board_rows[neighbor_row][neighbor_column]
                    if neighbor == stone:
                        nearby_friend = True
                    elif (
                        abs(row_delta) + abs(column_delta) == 1
                        and neighbor in ("B", "W")
                    ):
                        orthogonal_enemies += 1

            if not nearby_friend:
                detached[stone] += 1
            if orthogonal_enemies >= 2:
                pressured[stone] += 1

            if (row_index, column_index) in seen:
                continue

            group = [(row_index, column_index)]
            seen.add((row_index, column_index))
            liberties: set[tuple[int, int]] = set()

            for group_row, group_column in group:
                for neighbor_row, neighbor_column in (
                    (group_row - 1, group_column),
                    (group_row + 1, group_column),
                    (group_row, group_column - 1),
                    (group_row, group_column + 1),
                ):
                    if not (
                        0 <= neighbor_row < height
                        and 0 <= neighbor_column < width
                    ):
                        continue

                    neighbor = board_rows[neighbor_row][neighbor_column]
                    if neighbor == ".":
                        liberties.add((neighbor_row, neighbor_column))
                    elif (
                        neighbor == stone
                        and (neighbor_row, neighbor_column) not in seen
                    ):
                        seen.add((neighbor_row, neighbor_column))
                        group.append((neighbor_row, neighbor_column))

            liberty_count = len(liberties)
            group_size = len(group)

            if liberty_count <= 2:
                weak_burden[stone] += group_size * (3 - liberty_count)
            elif liberty_count >= 4:
                fortified[stone] += group_size * min(3, liberty_count - 3)

    if counts[color] == 0:
        return False

    def box_sum(row: int, column: int, radius: int) -> int:
        top = max(0, row - radius)
        bottom = min(height, row + radius + 1)
        left = max(0, column - radius)
        right = min(width, column + radius + 1)
        return (
            prefix[bottom][right]
            - prefix[top][right]
            - prefix[bottom][left]
            + prefix[top][left]
        )

    short_radius = 1
    middle_radius = max(2, min(height, width) // 6)
    long_radius = max(middle_radius + 1, min(height, width) // 3)
    control = 0

    for row_index, row in enumerate(board_rows):
        for column_index, point in enumerate(row):
            if point == color:
                control += 1
            elif point == opponent:
                control -= 1
            else:
                influence = (
                    4 * box_sum(row_index, column_index, short_radius)
                    + 2 * box_sum(row_index, column_index, middle_radius)
                    + box_sum(row_index, column_index, long_radius)
                )
                if influence > 0:
                    control += 1
                elif influence < 0:
                    control -= 1

    margin = float(control)
    margin += 7.5 if color == "W" else -7.5
    margin += 2.0 * (
        weak_burden[opponent] - weak_burden[color]
    )
    margin += 1.25 * (detached[opponent] - detached[color])
    margin += 1.5 * (pressured[opponent] - pressured[color])
    margin += 0.25 * (fortified[color] - fortified[opponent])

    return margin > 0.0

MOTIF_NAME = 'low-liberty burden advantage'
MOTIF_DESCRIPTION = 'The opponent has substantially more stones tied up in groups with only one or two liberties than the evaluated side.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    seen = set()
    burden = {color: 0, opp: 0}

    for r, row in enumerate(board_rows):
        for c, ch in enumerate(row):
            if ch == '.' or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            size = 0
            liberties = set()
            while stack:
                x, y = stack.pop()
                size += 1
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < 19 and 0 <= b < 19:
                        v = board_rows[a][b]
                        if v == '.':
                            liberties.add((a, b))
                        elif v == ch and (a, b) not in seen:
                            seen.add((a, b))
                            stack.append((a, b))
            if len(liberties) == 1:
                burden[ch] += 3 * size + 2
            elif len(liberties) == 2:
                burden[ch] += size

    return burden[opp] >= burden[color] + 3

MOTIF_NAME = "coprime-stride fortified influence polarity"
MOTIF_DESCRIPTION = (
    "The evaluated side has favorable fortified local influence after "
    "accounting for weak, detached, and pressured stones."
)


