            running += int(stone == color) - int(stone == opponent)
            prefix[row_index + 1][column_index + 1] = (
                prefix[row_index][column_index + 1] + running
            )

            if stone not in ("B", "W"):
                continue

            has_nearby_friend = False
            adjacent_enemies = 0
            for row_delta in (-1, 0, 1):
                for column_delta in (-1, 0, 1):
                    if row_delta == 0 and column_delta == 0:
                        continue
                    neighbor_row = row_index + row_delta
                    neighbor_column = column_index + column_delta
                    if (
