                        ):
                            adjacent_enemies += 1

            if not has_nearby_friend:
                detached[stone] += 1
            if adjacent_enemies >= 2:
                pressured[stone] += 1

            if (row_index, column_index) in seen:
                continue

            group = [(row_index, column_index)]
            seen.add((row_index, column_index))
            liberties = set()
            group_index = 0

            while group_index < len(group):
                group_row, group_column = group[group_index]
                group_index += 1
                for neighbor_row, neighbor_column in (
                    (group_row - 1, group_column),
                    (group_row + 1, group_column),
                    (group_row, group_column - 1),
                    (group_row, group_column + 1),
                ):
                    if not (
                        0 <= neighbor_row < height
                        and 0 <= neighbor_column < width
                    ):
                        continue
                    neighbor = board_rows[neighbor_row][neighbor_column]
                    if neighbor == ".":
                        liberties.add((neighbor_row, neighbor_column))
                    elif (
                        neighbor == stone
                        and (neighbor_row, neighbor_column) not in seen
                    ):
                        seen.add((neighbor_row, neighbor_column))
                        group.append((neighbor_row, neighbor_column))

            liberty_count = len(liberties)
            group_size = len(group)
            if liberty_count <= 2:
                weak[stone] += group_size * (3 - liberty_count)
            elif liberty_count >= 4:
                fortified[stone] += group_size * min(3, liberty_count - 3)

    def box_sum(row_index: int, column_index: int, radius: int) -> int:
        top = max(0, row_index - radius)
        bottom = min(height, row_index + radius + 1)
        left = max(0, column_index - radius)
        right = min(width, column_index + radius + 1)
        return (
            prefix[bottom][right]
            - prefix[top][right]
            - prefix[bottom][left]
            + prefix[top][left]
        )

    control = 0
    for row_index, row in enumerate(board_rows):
        for column_index, stone in enumerate(row):
            if stone == color:
                control += 1
            elif stone == opponent:
                control -= 1
            elif stone == ".":
                influence = (
                    4 * box_sum(row_index, column_index, 1)
                    + 2 * box_sum(row_index, column_index, 3)
                    + box_sum(row_index, column_index, 6)
                )
                control += int(influence > 0) - int(influence < 0)

    margin = (
        control
        + 7 * (fortified[color] - fortified[opponent])
        + 4 * (weak[opponent] - weak[color])
        + 2 * (detached[opponent] - detached[color])
        + 3 * (pressured[opponent] - pressured[color])
    )

    if margin != 0:
        return margin > 0

    area = height * width
    stride = max(2, width + 2)

    def gcd(first: int, second: int) -> int:
        while second:
            first, second = second, first % second
        return first

    while gcd(stride, area) != 1:
        stride += 1

    checksum = 0
    for index in range(area):
        row_index = index // width
        column_index = index % width
        stone = board_rows[row_index][column_index]
        weight = ((index * stride) % area) % 7 + 1
        if stone == color:
            checksum += weight
        elif stone == opponent:
            checksum -= weight

    return checksum > 0

MOTIF_NAME = 'detached stone burden advantage'
MOTIF_DESCRIPTION = 'The opponent has at least two more stones lacking any friendly support in their surrounding eight-point neighborhood.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    own_detached = enemy_detached = 0

    for r in range(19):
        for c in range(19):
            stone = board_rows[r][c]
            if stone == '.':
                continue
            supported = False
            for dr in (-1, 0, 1):
                rr = r + dr
                if not 0 <= rr < 19:
                    continue
                for dc in (-1, 0, 1):
                    cc = c + dc
                    if (dr or dc) and 0 <= cc < 19 and board_rows[rr][cc] == stone:
                        supported = True
            if not supported:
                if stone == color:
                    own_detached += 1
                elif stone == opp:
                    enemy_detached += 1

    return enemy_detached - own_detached >= 2

