                            liberties.add((nx, ny))
                        elif value == stone and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            group.append((nx, ny))

            size = len(group)
            libs = len(liberties)
            if libs <= 2:
                weak[stone] += size * (3 - libs)
            elif libs >= 4:
                fortified[stone] += size * min(3, libs - 3)

    prefix = [[0] * 20 for _ in range(20)]
    for r in range(19):
        running = 0
        for c in range(19):
            stone = board_rows[r][c]
            running += (stone == color) - (stone == opp)
            prefix[r + 1][c + 1] = prefix[r][c + 1] + running

    def box(r, c, radius):
        top = max(0, r - radius)
        bottom = min(19, r + radius + 1)
        left = max(0, c - radius)
        right = min(19, c + radius + 1)
        return (prefix[bottom][right] - prefix[top][right]
                - prefix[bottom][left] + prefix[top][left])

    control = 0
    for r in range(19):
        for c in range(19):
            stone = board_rows[r][c]
            if stone == color:
                control += 1
            elif stone == opp:
                control -= 1
            else:
                influence = 4 * box(r, c, 1) + 2 * box(r, c, 3) + box(r, c, 6)
                control += (influence > 0) - (influence < 0)

    score = control + (7.5 if color == 'W' else -7.5)
    score += 2 * (weak[opp] - weak[color])
    score += 1.25 * (detached[opp] - detached[color])
    score += 1.5 * (pressured[opp] - pressured[color])
    score += 0.25 * (fortified[color] - fortified[opp])

    phase = 1
    for axis in range(2):
        for line in range(19):
            last = -1
            previous = 0
            for p in range(19):
                r, c = (line, p) if axis == 0 else (p, line)
                stone = board_rows[r][c]
                if stone == '.':
                    continue
                code = 1 if stone == color else 2
                gap = p - last - 1
                phase = (131 * phase + 7 * gap + 31 * code
                         + 17 * (previous != code) + 5 * line + axis) % 283
                last = p
                previous = code

    return (score > 0) != (phase < 95)

MOTIF_NAME = 'diagonal-prime composite pressure polarity'
MOTIF_DESCRIPTION = 'The evaluated side has favorable layered influence corrected for weak-chain burden after adjustment by a diagonal prime-cycle checksum.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    prefix = [[0] * 20 for _ in range(20)]
    burden = {'B': 0, 'W': 0}
    seen = set()
    phase = 0

    for r, row in enumerate(board_rows):
        run = 0
        for c, stone in enumerate(row):
            run += (stone == 'B') - (stone == 'W')
            prefix[r + 1][c + 1] = prefix[r][c + 1] + run

            if stone == '.' or (r, c) in seen:
                continue
            group = [(r, c)]
            seen.add((r, c))
            liberties = set()
            for x, y in group:
                for nx, ny in ((x - 1, y), (x + 1, y),
                               (x, y - 1), (x, y + 1)):
                    if 0 <= nx < 19 and 0 <= ny < 19:
                        value = board_rows[nx][ny]
                        if value == '.':
                            liberties.add((nx, ny))
                        elif value == stone and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            group.append((nx, ny))
            if len(liberties) <= 2:
                burden[stone] += len(group)

    for diagonal in range(37):
        points = [(r, diagonal - r)
                  for r in range(max(0, diagonal - 18), min(18, diagonal) + 1)]
        if diagonal % 2:
            points.reverse()
        for r, c in points:
            stone = board_rows[r][c]
            code = 3 if stone == color else 10 if stone == opp else 0
            weight = ((r + 2) ** 3 + 5 * (c + 3) ** 2
                      + 7 * (r + 1) * (c + 1) + 11 * diagonal + 1)
            phase = (phase * 61 + code * weight) % 101

    def box(r, c, radius):
        a, b = max(0, r - radius), min(19, r + radius + 1)
        x, y = max(0, c - radius), min(19, c + radius + 1)
        return prefix[b][y] - prefix[a][y] - prefix[b][x] + prefix[a][x]

    balance = 0
    for r, row in enumerate(board_rows):
        for c, stone in enumerate(row):
            if stone == 'B':
                balance += 1
            elif stone == 'W':
                balance -= 1
            else:
                influence = 4 * box(r, c, 1) + 2 * box(r, c, 3) + box(r, c, 6)
                balance += (influence > 0) - (influence < 0)

    margin = balance - 7.5 if color == 'B' else 7.5 - balance
    margin += 2 * (burden[opp] - burden[color])
    return (margin > 0) != (phase < 31)

MOTIF_NAME = 'peripheral Voronoi control lead'
MOTIF_DESCRIPTION = 'The evaluated side has a komi-adjusted lead in outer-board points assigned to the nearest stone by Manhattan distance.'
def motif(board_rows: list[str], color: str) -> bool:
    def distances(stone):
        d = [99] * 361
        for r in range(19):
            row = board_rows[r]
            for c in range(19):
                p = r * 19 + c
                if row[c] == stone:
                    d[p] = 0
