            if a[c] in count and a[c] == b[c + 2] and a[c + 1:c + 3] == '..' and b[c:c + 2] == '..':
                count[a[c]] += 1
            if b[c] in count and b[c] == a[c + 2] and b[c + 1:c + 3] == '..' and a[c:c + 2] == '..':
                count[b[c]] += 1

    for r in range(17):
        for c in range(18):
            x = board_rows[r][c]
            if (x in count and x == board_rows[r + 2][c + 1]
                    and board_rows[r][c + 1] == board_rows[r + 1][c] == board_rows[r + 1][c + 1] == board_rows[r + 2][c] == '.'):
                count[x] += 1
            x = board_rows[r][c + 1]
            if (x in count and x == board_rows[r + 2][c]
                    and board_rows[r][c] == board_rows[r + 1][c] == board_rows[r + 1][c + 1] == board_rows[r + 2][c + 1] == '.'):
                count[x] += 1

    return count[color] > count[opp]

MOTIF_NAME = 'diagonal enclosure surplus'
MOTIF_DESCRIPTION = 'The evaluated side controls more empty points supported by favorable nearest stones along diagonal rays.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    sight = [0] * 361

    def scan(starts, dr, dc):
        for r, c in starts:
            last = 0
            while 0 <= r < 19 and 0 <= c < 19:
                stone = board_rows[r][c]
                if stone == color:
                    last = 1
                elif stone == opp:
                    last = -1
                else:
                    sight[r * 19 + c] += last
                r += dr
                c += dc

    scan([(0, c) for c in range(19)] + [(r, 0) for r in range(1, 19)], 1, 1)
    scan([(18, c) for c in range(19)] + [(r, 18) for r in range(18)], -1, -1)
    scan([(0, c) for c in range(19)] + [(r, 18) for r in range(1, 19)], 1, -1)
    scan([(18, c) for c in range(19)] + [(r, 0) for r in range(18)], -1, 1)

    lead = 0
    for i, stone in enumerate(''.join(board_rows)):
        if stone == '.':
            lead += sight[i] >= 2
            lead -= sight[i] <= -2
    return lead >= 4
